import gzip,csv,json,re,numpy as np
id2name=json.load(open('id2name.json'))
with gzip.open('sample.swap.rna.q1.tsv.gz','rt') as f:
    r=csv.reader(f,delimiter='\\t'); h=next(r); cols=h[1:]; rows=[]
    for row in r: rows.append((row[0],[float(x) for x in row[1:]]))
A=np.array([v for _,v in rows]); ids=[g for g,_ in rows]
print(cols)
patterns=['CHGA','CHGB','SCGN','DDC','SLC18','TPH','SST','INSM','NEUROD','PCSK','CPE','POMC','TSH','GHRH','NPY','VIP','TAC','NTS','GAL','PYY','PPY','GCG','INS','GHRL','SLC17','SLC6A','SLC32','GAD','TH"'$'"','DBH','PAX4','NKX2-2','ARX','ISL1','MNX1','RFX6','FEV','LMX1','PITX','OTP','NEUROG3']
for p in patterns:
    rr=re.compile('"'^'"'+p,re.I)
    m=[]
    for i,g in enumerate(ids):
        n=id2name.get(g,g)
        if rr.search(n): m.append((n,g,A[i]))
    if m:
        print('\\n##',p)
        for n,g,v in m[:15]: print(f'{n:12s} {g:15s} ' + ' '.join(f'{x:7.1f}' for x in v))
PY"

